"""Portable design approximation. Android evidence is generated by capture_android.py."""
import argparse,io,math
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont,ImageOps,ImageChops
from validate import load
from scene import local,mul,inverse,IDENTITY,translate,around

def preview(package,output,title='Midnight in Seoul',artist='Luna Park',playing=True,artwork=None,fallback_font=None,time_ms=0,animate=False,position=84000,duration=222000):
    m,files=load(package); size=(m['width'],m['height'])
    def time(value): return f'{value//60000}:{value//1000%60:02d}'
    values={'elapsed':time(position) if duration>0 else '—','duration':time(duration) if duration>0 else '—','title':title,'artist':artist,'album':'City Lights','player':'YouTube Music','status':'재생 중' if playing else '일시 정지'}
    def asset(src): return Image.open(io.BytesIO(files[src])).convert('RGBA')
    def warp(tile,matrix):
        v=inverse(matrix); v=tuple(x/v[8] for x in v)
        return tile.transform(size,Image.Transform.PERSPECTIVE,v[:8],Image.Resampling.BICUBIC)
    def draw_node(n,parent):
        empty=Image.new('RGBA',size); visible=n.get('visibleWhen','always')
        if visible=='playing' and not playing or visible=='paused' and playing or visible=='hasArtwork' and not artwork or visible=='noArtwork' and artwork: return empty
        w,h=max(1,round(n['w'])),max(1,round(n['h'])); matrix=mul(parent,local(n)); alpha=n.get('opacity',1)
        a=n.get('animation'); active=animate and a and (playing or a['when']=='always')
        if active:
            phase=(time_ms%a['durationMs'])/a['durationMs']; ping=1-abs(2*phase-1)
            if a['kind']=='rotate':
                angle=math.radians(a.get('from',0)+(a.get('to',360)-a.get('from',0))*phase); cs,sn=math.cos(angle),math.sin(angle)
                matrix=mul(matrix,around((cs,-sn,0,sn,cs,0,0,0,1),w/2,h/2))
            elif a['kind']=='translate': matrix=mul(matrix,translate(a.get('dx',0)*ping,a.get('dy',0)*ping))
            elif a['kind']=='pulse': alpha*=a.get('from',.35)+(a.get('to',1)-a.get('from',.35))*ping
        tile=Image.new('RGBA',(w,h)); d=ImageDraw.Draw(tile); kind=n['type']
        if kind=='group':
            layer=empty
            for child in n['children']: layer.alpha_composite(draw_node(child,matrix))
        else:
            if kind=='shape':
                shape=n['shape']; color=n['color']; stroke=n.get('strokeColor'); sw=round(n.get('strokeWidth',0))
                if shape=='ellipse': d.ellipse((0,0,w-1,h-1),fill=color,outline=stroke,width=sw)
                elif shape=='polygon': d.polygon([(n['points'][i]*w,n['points'][i+1]*h) for i in range(0,len(n['points']),2)],fill=color,outline=stroke,width=sw)
                else: d.rounded_rectangle((0,0,w-1,h-1),radius=n.get('radius',0),fill=color,outline=stroke,width=sw)
                if 'gradient' in n:
                    start=tuple(bytes.fromhex(color[1:])); end=tuple(bytes.fromhex(n['gradient']['endColor'][1:])); angle=math.radians(n['gradient']['angle']); dx,dy=math.cos(angle)*w/2,math.sin(angle)*h/2; den=4*(dx*dx+dy*dy)
                    pixels=[]
                    for y in range(h):
                        for x in range(w):
                            f=max(0,min(1,((x-w/2+dx)*2*dx+(y-h/2+dy)*2*dy)/den))
                            pixels.append(tuple(round(start[i]+(end[i]-start[i])*f) for i in range(3))+(255,))
                    gradient=Image.new('RGBA',(w,h)); gradient.putdata(pixels); gradient.putalpha(tile.getchannel('A')); tile=gradient
            elif kind=='equalizer':
                t=time_ms/1000 if animate and playing and n['mode']=='simulated' else 0
                for i in range(n['bars']):
                    value=.15+.85*abs(math.sin(i*1.73+n.get('seed',7)+t*(1+i%3)))
                    d.rectangle((i*w/n['bars'],h*(1-value),(i+1-n.get('gap',.25))*w/n['bars'],h),fill=n['color'])
            elif kind=='text':
                font=ImageFont.truetype(io.BytesIO(files[n['font']]),round(n['size'])); value=n.get('text','') if n['field']=='literal' else values[n['field']]
                overflow=n.get('overflow','ellipsis'); lines=[]
                if overflow=='wrap':
                    current=''
                    for ch in value:
                        if ch=='\n' or current and d.textlength(current+ch,font=font)>w: lines.append(current); current='' if ch=='\n' else ch
                        else: current+=ch
                    lines.append(current); lines=lines[:n.get('maxLines',3)]
                else: lines=[value]
                moving=overflow=='marquee' and animate and playing and d.textlength(value,font=font)>w
                if overflow not in ('clip','wrap') and not moving:
                    line=lines[0]
                    if d.textlength(line,font=font)>w:
                        while line and d.textlength(line+'…',font=font)>w: line=line[:-1]
                        line+='…'
                    lines=[line]
                ascent,descent=font.getmetrics(); line_height=(ascent+descent)*n.get('lineSpacing',1); block_height=line_height*len(lines)
                y={'top':0,'center':(h-block_height)/2,'bottom':h-block_height}[n.get('valign','top')]
                for line in lines:
                    tw=d.textlength(line,font=font); x={'left':0,'center':(w-tw)/2,'right':w-tw}[n.get('align','left')]
                    if moving:
                        distance=tw+w/3; x=-(time_ms%12000)/12000*distance; d.text((x+distance,y+ascent),line,font=font,fill=n['color'],anchor='ls')
                    d.text((x,y+ascent),line,font=font,fill=n['color'],anchor='ls'); y+=line_height
            elif kind=='progress':
                fraction=max(0,min(1,position/duration)) if duration>0 else 0; direction=n.get('direction','horizontal'); r=n.get('radius',h/2)
                if direction=='circular':
                    sw=round(n.get('strokeWidth',6)); start=n.get('startAngle',-90); sweep=n.get('sweepAngle',360)
                    d.arc((sw/2,sw/2,w-sw/2,h-sw/2),start,start+sweep,fill=n['trackColor'],width=sw)
                    if n.get('showFill',True) and fraction>0: d.arc((sw/2,sw/2,w-sw/2,h-sw/2),start,start+sweep*fraction,fill=n['color'],width=sw)
                else:
                    if 'trackSrc' in n: tile.alpha_composite(asset(n['trackSrc']).resize((w,h)))
                    else: d.rounded_rectangle((0,0,w,h),radius=r,fill=n['trackColor'])
                    box=(0,round(h*(1-fraction)),w,h) if direction=='vertical' else (0,0,round(w*fraction),h)
                    if n.get('showFill',True) and fraction>0:
                        if 'fillSrc' in n:
                            fill=asset(n['fillSrc']).resize((w,h)).crop(box); tile.alpha_composite(fill,box[:2])
                        else: d.rounded_rectangle(box,radius=r,fill=n['color'])
                    if 'thumbSrc' in n and duration>0:
                        tw=round(n['thumbWidth'])
                        if direction=='vertical':
                            th=min(tw,h); tile.alpha_composite(asset(n['thumbSrc']).resize((w,th)),(0,round((h-th)*(1-fraction))))
                        else: tile.alpha_composite(asset(n['thumbSrc']).resize((tw,h)),(round((w-tw)*fraction),0))
            else:
                src=n.get('src',n.get('fallback'))
                if kind=='icon' and n['action']=='toggle' and playing: src=n.get('playingSrc',src)
                if active and a['kind']=='frames': src=a['sources'][min(len(a['sources'])-1,int(phase*len(a['sources'])))]
                image=Image.open(artwork).convert('RGBA') if kind=='artwork' and artwork and not(active and a['kind']=='frames') else asset(src)
                fit=n.get('fit','crop' if kind=='artwork' else 'stretch')
                if fit=='crop': tile=ImageOps.fit(image,(w,h))
                elif fit=='contain':
                    image=ImageOps.contain(image,(w,h)); tile.alpha_composite(image,((w-image.width)//2,(h-image.height)//2))
                else: tile=image.resize((w,h),Image.Resampling.LANCZOS)
            layer=warp(tile,matrix)
        if n.get('mask','none')!='none' or 'maskSrc' in n:
            mask=Image.new('RGBA',(w,h)); draw=ImageDraw.Draw(mask)
            if n.get('mask')=='circle':
                radius=min(w,h)/2; draw.ellipse((w/2-radius,h/2-radius,w/2+radius,h/2+radius),fill='white')
            elif n.get('mask')=='rounded': draw.rounded_rectangle((0,0,w,h),radius=n.get('radius',min(w,h)/8),fill='white')
            else: draw.rectangle((0,0,w,h),fill='white')
            if 'maskSrc' in n: mask.putalpha(ImageChops.multiply(mask.getchannel('A'),asset(n['maskSrc']).resize((w,h)).getchannel('A')))
            layer.putalpha(ImageChops.multiply(layer.getchannel('A'),warp(mask,matrix).getchannel('A')))
        if alpha<1: layer.putalpha(layer.getchannel('A').point(lambda v: round(v*alpha)))
        return layer
    result=Image.new('RGBA',size)
    for node in m['layers']: result.alpha_composite(draw_node(node,IDENTITY))
    Path(output).parent.mkdir(parents=True,exist_ok=True); result.save(output)

if __name__=='__main__':
    p=argparse.ArgumentParser(); p.add_argument('package'); p.add_argument('output'); p.add_argument('--title',default='Midnight in Seoul'); p.add_argument('--artist',default='Luna Park'); p.add_argument('--paused',action='store_true'); p.add_argument('--artwork'); p.add_argument('--fallback-font'); p.add_argument('--time-ms',type=int,default=0); p.add_argument('--animate',action='store_true'); a=p.parse_args()
    preview(a.package,a.output,a.title,a.artist,not a.paused,a.artwork,a.fallback_font,a.time_ms,a.animate)
